export const MONUMENTS = JSON.parse("[{\"id\":\"n6080481771\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3263.3,\"z\":194.6,\"subject\":\"Q4333233\",\"inscription\":\"Здесь, в казармах 2-го Балтийского флота экипажа, в дни Октябрьского вооруженного восстания находился полевой штаб левого фланга революционных войск, наступавших на Зимний дворец\"},{\"id\":\"n6080481772\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. М. Кошке\",\"x\":-3252.6,\"z\":188.9,\"subject\":\"Q4237049\",\"inscription\":\"В этом доме в 1860-х годах проходил службу герой обороны Севастополя в годы Крымской (Восточной) войны 1853-1856 годов, Георгиевский кавалер квартирмейстер Петр Маркович Кошка\"},{\"id\":\"n12070262789\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Ф. Ф. Ушаков\",\"x\":-3267.8,\"z\":164.5,\"inscription\":\"Адмирал Федор Федорович Ушаков 1745-1817 святой праведный воин\"},{\"id\":\"n8732344511\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Адмиралтейскому каналу\",\"x\":-3300,\"z\":109.1,\"subject\":\"Q4057892\",\"inscription\":\"Здесь проходил Адмиралтейский канал. Проложен в 1717 году, соединял Адмиралтейство и Новую Голландию. В 1844 году заключен в каменную трубу и засыпан. На его месте устроен Конногвардейский бульвар.\"},{\"id\":\"n8947094298\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Б. В. Асафьеву\",\"x\":-3222.2,\"z\":112.6,\"subject\":\"Q325032\",\"inscription\":\"В этом доме с 1933 по 1943 г. жил и работал Народный артист Союза С.С.Р. академик Борис Владимирович Асафьев\"}]");
